/* Fast dominant eigenpair for small real matrices.
 *
 * Calls LAPACK (ILP64 symbols from numpy's bundled scipy-openblas) through
 * dlsym, computes eigenvalues with dgeev (no eigenvectors), then recovers the
 * dominant eigenvector with shifted inverse iteration on a reused LU
 * factorization.
 */
#include <dlfcn.h>
#include <math.h>
#include <stdint.h>
#include <string.h>

typedef int64_t i64;

typedef void (*geev_t)(char *, char *, i64 *, double *, i64 *, double *,
                       double *, double *, i64 *, double *, i64 *, double *,
                       i64 *, i64 *);
typedef void (*dgetrf_t)(i64 *, i64 *, double *, i64 *, i64 *, i64 *);
typedef void (*dgetrs_t)(char *, i64 *, i64 *, double *, i64 *, i64 *,
                         double *, i64 *, i64 *);
typedef void (*zgetrf_t)(i64 *, i64 *, void *, i64 *, i64 *, i64 *);
typedef void (*zgetrs_t)(char *, i64 *, i64 *, void *, i64 *, i64 *, void *,
                         i64 *, i64 *);

static geev_t f_geev;
static dgetrf_t f_dgetrf;
static dgetrs_t f_dgetrs;
static zgetrf_t f_zgetrf;
static zgetrs_t f_zgetrs;

#define MAXN 16

int kod_init(const char *path) {
    void *h = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    if (!h) return -1;
    *(void **)(&f_geev) = dlsym(h, "scipy_dgeev_64_");
    *(void **)(&f_dgetrf) = dlsym(h, "scipy_dgetrf_64_");
    *(void **)(&f_dgetrs) = dlsym(h, "scipy_dgetrs_64_");
    *(void **)(&f_zgetrf) = dlsym(h, "scipy_zgetrf_64_");
    *(void **)(&f_zgetrs) = dlsym(h, "scipy_zgetrs_64_");
    if (!f_geev || !f_dgetrf || !f_dgetrs || !f_zgetrf || !f_zgetrs)
        return -2;
    return 0;
}

static const double seed[MAXN] = {
    0.617, -0.231, 0.902, 0.113, -0.771, 0.344, -0.519, 0.827,
    -0.061, 0.485, -0.933, 0.258, 0.706, -0.397, 0.138, -0.658};

static double norm2(int n, const double *x) {
    double s = 0.0;
    for (int i = 0; i < n; i++) s += x[i] * x[i];
    return sqrt(s);
}

static double norm2c(int n, const double *x) {
    double s = 0.0;
    for (int i = 0; i < n; i++) s += x[2 * i] * x[2 * i] + x[2 * i + 1] * x[2 * i + 1];
    return sqrt(s);
}

/* Returns 0 on success. */
int kod_dominant(int n, const double *A, double *val, double *vec,
                 int *is_complex) {
    if (n < 1 || n > MAXN) return -1;

    double a[MAXN * MAXN];
    double wr[MAXN], wi[MAXN], work[8 * MAXN];
    i64 nn = n, one = 1, ld = n, lw = 8 * n, info = 0;
    char jobn = 'N', jobv = 'V', trans = 'N';

    double anorm = 0.0;
    for (int j = 0; j < n; j++) {
        double col = 0.0;
        for (int i = 0; i < n; i++) {
            double x = A[i * n + j];
            a[i + j * n] = x; /* Fortran order */
            col += fabs(x);
        }
        if (col > anorm) anorm = col;
    }

    f_geev(&jobn, &jobn, &nn, a, &ld, wr, wi, 0, &one, 0, &one, work, &lw,
           &info);
    if (info != 0) return -3;

    int k = 0;
    double best = wr[0] * wr[0] + wi[0] * wi[0];
    for (int i = 1; i < n; i++) {
        double t = wr[i] * wr[i] + wi[i] * wi[i];
        if (t > best) { best = t; k = i; }
    }

    double lam_re = wr[k], lam_im = wi[k];
    double scale = 1.0 + fabs(lam_re) + fabs(lam_im);
    if (anorm > scale) scale = anorm;

    if (lam_im == 0.0) {
        /* ---- real eigenvalue ---- */
        double delta = 1e-10 * scale;
        double lu[MAXN * MAXN], b[MAXN];
        i64 ipiv[MAXN];
        int ok = 0;
        for (int attempt = 0; attempt < 2 && !ok; attempt++) {
            double mu = lam_re + delta;
            for (int j = 0; j < n; j++)
                for (int i = 0; i < n; i++)
                    lu[i + j * n] = A[i * n + j];
            for (int i = 0; i < n; i++) lu[i + i * n] -= mu;
            info = 0;
            f_dgetrf(&nn, &nn, lu, &ld, ipiv, &info);
            if (info != 0) { delta *= 1e4; continue; }

            for (int i = 0; i < n; i++) b[i] = seed[i];
            for (int it = 0; it < 2; it++) {
                f_dgetrs(&trans, &nn, &one, lu, &ld, ipiv, b, &ld, &info);
                if (info != 0) break;
                if (it == 0) {
                    double s = norm2(n, b);
                    if (s == 0.0 || !isfinite(s)) break;
                    for (int i = 0; i < n; i++) b[i] /= s;
                }
            }
            if (info != 0) { delta *= 1e4; continue; }
            double s = norm2(n, b);
            if (!(s > 0.0) || !isfinite(s)) { delta *= 1e4; continue; }
            for (int i = 0; i < n; i++) b[i] /= s;

            /* residual check: ||A b - lam b|| / (anorm*||b|| + |lam|*||b||) */
            double r2 = 0.0;
            for (int i = 0; i < n; i++) {
                double t = -lam_re * b[i];
                for (int j = 0; j < n; j++) t += A[i * n + j] * b[j];
                r2 += t * t;
            }
            double denom = (anorm + fabs(lam_re)) * s;
            if (sqrt(r2) <= 1e-9 * denom + 1e-13) {
                ok = 1;
                memcpy(vec, b, (size_t)n * sizeof(double));
                for (int i = n - 1; i >= 0; i--) vec[2 * i] = vec[i];
                for (int i = 0; i < n; i++) vec[2 * i + 1] = 0.0;
            } else {
                delta *= 1e4;
            }
        }
        if (!ok) return -4;
        val[0] = lam_re;
        val[1] = 0.0;
        *is_complex = 0;
        return 0;
    }

    /* ---- complex eigenvalue ---- */
    double delta = 1e-10 * scale;
    double clu[2 * MAXN * MAXN], cb[2 * MAXN];
    i64 ipiv[MAXN];
    int ok = 0;
    for (int attempt = 0; attempt < 2 && !ok; attempt++) {
        double mu_re = lam_re + delta, mu_im = lam_im;
        for (int j = 0; j < n; j++)
            for (int i = 0; i < n; i++) {
                clu[2 * (i + j * n)] = A[i * n + j];
                clu[2 * (i + j * n) + 1] = 0.0;
            }
        for (int i = 0; i < n; i++) {
            clu[2 * (i + i * n)] -= mu_re;
            clu[2 * (i + i * n) + 1] -= mu_im;
        }
        info = 0;
        f_zgetrf(&nn, &nn, clu, &ld, ipiv, &info);
        if (info != 0) { delta *= 1e4; continue; }

        for (int i = 0; i < n; i++) { cb[2 * i] = seed[i]; cb[2 * i + 1] = 0.0; }
        for (int it = 0; it < 2; it++) {
            f_zgetrs(&trans, &nn, &one, clu, &ld, ipiv, cb, &ld, &info);
            if (info != 0) break;
            if (it == 0) {
                double s = norm2c(n, cb);
                if (s == 0.0 || !isfinite(s)) break;
                for (int i = 0; i < 2 * n; i++) cb[i] /= s;
            }
        }
        if (info != 0) { delta *= 1e4; continue; }
        double s = norm2c(n, cb);
        if (!(s > 0.0) || !isfinite(s)) { delta *= 1e4; continue; }
        for (int i = 0; i < 2 * n; i++) cb[i] /= s;

        /* complex residual */
        double r2 = 0.0;
        for (int i = 0; i < n; i++) {
            double tr = -lam_re * cb[2 * i] + lam_im * cb[2 * i + 1];
            double ti = -lam_re * cb[2 * i + 1] - lam_im * cb[2 * i];
            for (int j = 0; j < n; j++) {
                tr += A[i * n + j] * cb[2 * j];
                ti += A[i * n + j] * cb[2 * j + 1];
            }
            r2 += tr * tr + ti * ti;
        }
        double denom = (anorm + fabs(lam_re) + fabs(lam_im)) * s;
        if (sqrt(r2) <= 1e-9 * denom + 1e-13) {
            ok = 1;
        } else {
            delta *= 1e4;
        }
    }
    if (!ok) return -4;
    memcpy(vec, cb, (size_t)(2 * n) * sizeof(double));
    val[0] = lam_re;
    val[1] = lam_im;
    *is_complex = 1;
    return 0;
}

